+     the sidebar/TOC `top` offsets and the content padding line up with it. */
+  --sl-nav-height: 3.25rem;
+}
+
+/* The shared <flatbars-topbar> (the Header override) IS the bar now — it carries
+   its own background, blur and border. Neutralise Starlight's native header band
+   so the element's chrome is the only thing that shows (customCss is unlayered,
+   so this beats Starlight's @layer starlight.core .header rules). */
+.header {
+  padding: 0;
+  background: transparent;
+  border-bottom: 0;
 }

